/**
 * 描述结构放置旋转的枚举。
 */
export enum StructureRotation {
    /**
     * @remarks
     * 不旋转。
     *
     */
    None = 'None',
    /**
     * @remarks
     * 180度旋转。
     *
     */
    Rotate180 = 'Rotate180',
    /**
     * @remarks
     * 270度旋转。
     *
     */
    Rotate270 = 'Rotate270',
    /**
     * @remarks
     * 90度旋转。
     *
     */
    Rotate90 = 'Rotate90',
}